from pathlib import Path
from html import escape
from hashlib import sha256
import re
r=Path(__file__).resolve().parent.parent
# Content-addressed assets keep HTML and its styling paired across deploys.
asset_urls={}
for asset_name in ('site.css','organic.css','site.js'):
 data=(r/'assets'/asset_name).read_bytes()
 source=Path(asset_name)
 versioned=f'{source.stem}.{sha256(data).hexdigest()[:12]}{source.suffix}'
 (r/'assets'/versioned).write_bytes(data)
 asset_urls[asset_name]='assets/'+versioned
nav=[('about.html','About'),('programs.html','The vision'),('why-it-matters.html','Social media data')]
def page(file,title,description,body):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if file==url else '')+f'>{label}</a>' for url,label in nav)
 html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · Follow the Wild</title><meta name="description" content="{escape(description)}"><meta property="og:title" content="{title} · Follow the Wild"><meta property="og:description" content="{escape(description)}"><meta property="og:image" content="https://followthewild.org/assets/share.jpg"><meta name="theme-color" content="#101b16"><link rel="canonical" href="https://followthewild.org/{'' if file=='index.html' else file}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="{asset_urls['site.css']}"><link rel="stylesheet" href="{asset_urls['organic.css']}"><script src="{asset_urls['site.js']}" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-nav"><a class="brand" href="index.html"><svg class="brand-paw" viewBox="0 0 24 28" aria-hidden="true"><g fill="currentColor"><ellipse cx="12" cy="19" rx="6" ry="5.5"/><ellipse cx="4.2" cy="11" rx="2.2" ry="3"/><ellipse cx="9" cy="6" rx="2.3" ry="3.2"/><ellipse cx="15" cy="6" rx="2.3" ry="3.2"/><ellipse cx="19.8" cy="11" rx="2.2" ry="3"/></g></svg> FOLLOW THE WILD</a><nav aria-label="Main navigation">{links}<a class="creator-nav" href="get-involved.html">For creators</a><a class="button small" href="support.html#donate">Donate</a></nav><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-nav">Menu +</button></header><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>{links}<a href="get-involved.html">For creators</a><a href="support.html#donate">Donate</a></nav><main id="main">{body}</main><footer><div class="footer-top"><a class="brand" href="index.html"><span class="brand-symbol">✳</span> FOLLOW THE WILD</a><p>More voices. More wonder.<br>A generation that cares.</p><div class="footer-links">{links}<a href="get-involved.html">For creators</a><a href="support.html">Support the work ↗</a></div></div><div class="footer-base"><span>© 2026 Follow the Wild · A wildlife nonprofit</span><span>For the next generation. For the wild.</span><button id="motion-toggle" aria-pressed="false">Pause motion</button></div></footer></body></html>'''
 html=html.replace('</head>', '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@900&display=swap"></head>')
 if file!='index.html':
  html=html.replace('<body>', '<body class="inner-page">')
 html=re.sub(r'href="([a-z-]+\.html)(#[^"]*)?"', lambda m: 'href="'+m[1]+'?release=20261019-1'+(m[2] or '')+'"', html)
 (r/file).write_text(html)
def cta():
 return '''<section class="closing"><img src="assets/photos/humpback-dive.jpg" alt="A humpback whale beneath the surface" loading="lazy"><div class="wrap"><p class="eyebrow">The next chapter is ours to make</p><h2 class="reveal">You tell stories.<br><em>Let’s change the story.</em></h2><a class="button" href="get-involved.html">Register your interest <span>↗</span></a></div></section>'''
def hero(kicker,heading,text,img):
 return f'<section class="page-hero"><img src="assets/photos/{img}" alt="" class="hero-image"><div class="wrap"><p class="eyebrow">{kicker}</p><h1>{heading}</h1><p class="intro">{text}</p></div></section>'
network='''<div class="network" aria-label="Filmmakers, photographers, digital creators and storytellers connecting with one another and with the wild"><svg viewBox="0 0 600 440" aria-hidden="true"><g class="network-lines"><path class="peer-flow" d="M110 90Q300 -10 490 90M490 90Q590 220 490 350M490 350Q300 450 110 350M110 350Q10 220 110 90"/><path class="inward-flow" d="M110 90Q220 90 300 220M490 90Q380 90 300 220M490 350Q380 350 300 220M110 350Q220 350 300 220"/></g><circle class="orbit" cx="300" cy="220" r="145"/></svg><span class="node n1">Filmmakers</span><span class="node n2">Photographers</span><span class="node n3">Digital creators</span><span class="node n4">Storytellers</span><span class="node center">THE<br><b>WILD</b></span><span class="network-caption">Different voices. A shared purpose.</span></div>'''


def collaboration_concepts():
 return '''<section class="section concepts" id="possibilities"><div class="wrap"><div class="section-top"><div><p class="eyebrow">Imagine the possibilities</p><h2 class="reveal">What could we<br>make <em>together?</em></h2></div><p class="concept-intro">A few ways collaboration could bring wildlife to new audiences. These are creative possibilities, not announced or funded projects.</p></div><div class="concept-grid"><article class="concept-card reveal"><div class="concept-image"><img src="assets/photos/filmmaker-river.jpg" alt="A wildlife filmmaker working beside a river" loading="lazy"><span class="format-tag">WATCH / YOUTUBE</span></div><div class="concept-copy"><p class="eyebrow">Field filmmaker × digital creator</p><h3>One wild encounter.<br>Two ways to see it.</h3><p>A filmmaker shares their field knowledge. A creator brings their audience along. Together, they turn a wildlife encounter into a story made for YouTube.</p></div></article><article class="concept-card reveal"><div class="concept-image"><img src="assets/photos/field/tiger-rock.jpg" alt="A tiger moving over rocks" loading="lazy"><span class="format-tag">STREAM / LIVE</span></div><div class="concept-copy"><p class="eyebrow">Photographer × live creator</p><h3>Behind the shot.<br>Into the conversation.</h3><p>A wildlife photographer and a streamer unpack the story behind an image, with the audience asking questions as the conversation unfolds.</p></div></article><article class="concept-card reveal"><div class="concept-image"><img src="assets/photos/field/crested-eagle.jpg" alt="A crested eagle perched on a branch" loading="lazy"><span class="format-tag">SHARE / SHORT FORM</span></div><div class="concept-copy"><p class="eyebrow">Creator × creator</p><h3>Your neighborhood.<br>A whole new world.</h3><p>Two creators trade local wildlife discoveries in a shared short-form series, inviting their audiences to find something wild close to home.</p></div></article></div><a class="text-link" href="get-involved.html">What would you make? ↗</a></div></section>'''

def funding_band():
 return '''<section class="funding-band"><div class="wrap funding-inner"><div><p class="eyebrow">Help make it possible</p><h2 class="reveal">Back the creators.<br><em>Bring the wild closer.</em></h2><p>Help build funding for collaborative wildlife content made for the next generation. Your support can help turn shared ideas into stories worth watching.</p></div><div class="funding-action"><a class="button" href="support.html#donate">Donate</a><span>Explore the donation demo</span></div></div></section>'''

home='''<section class="hero reference-hero"><img class="hero-image" src="assets/photos/baby-gorilla.jpg" alt="A young mountain gorilla looking out from the leaves" fetchpriority="high"><div class="hero-lines" aria-hidden="true"></div><div class="hero-content wrap"><h1 aria-label="Follow the Wild"><span class="verb-slot" aria-hidden="true"><span id="hero-verb">Follow</span></span><span class="wild-word" aria-hidden="true"><span class="hero-the">The</span> Wild.</span></h1><div class="hero-bottom"><p>Make the next generation care about wildlife,<br>and GET OUTSIDE.</p><a class="button" href="get-involved.html">Create for the wild</a><a class="button hero-secondary" href="programs.html">Explore the vision</a></div><div class="hero-caption"><span>YOUTUBE / TIKTOK / INSTAGRAM / LIVE STREAMS</span><a href="#the-idea">Scroll to explore ↓</a></div></div><div class="hero-index" aria-hidden="true"><span id="verb-number">01</span> / 04</div></section>
<div class="platform-statement"><span>THE VISION</span><p>Fund creator collaborations.<br class="mobile-break"> Bring the wild to younger audiences.</p></div><div class="ticker" aria-hidden="true"><div>FOLLOW THE WILD <i>✳</i> WATCH THE WILD <i>✳</i> STREAM THE WILD <i>✳</i> SHARE THE WILD <i>✳</i> FOLLOW THE WILD <i>✳</i> WATCH THE WILD <i>✳</i> STREAM THE WILD <i>✳</i> SHARE THE WILD <i>✳</i></div></div>
<section class="section light" id="the-idea"><div class="wrap manifesto"><p class="eyebrow">01 / One wild idea</p><h2 class="reveal">The wild has<br>incredible storytellers.<br><em>Let’s bring them together.</em></h2><div class="offset-copy reveal"><p>The next great wildlife story could be a YouTube collaboration, a TikTok series, an Instagram Reel or a live stream. We want to help creators make it together.</p><p>Follow the Wild exists to make the next generation care about wildlife and want to get outside. Our focus is the creator economy: supporting collaborative projects made for the platforms where young people watch.</p><a class="text-link" href="about.html">Meet the mission ↗</a></div></div></section>
<section class="section"><div class="wrap two-col"><div><p class="eyebrow">02 / Make it together</p><h2 class="reveal">Great stories<br>travel further<br><em>together.</em></h2><p class="body-copy">A wildlife filmmaker and a YouTuber. A photographer and a streamer. Two creators introducing their audiences to a world they haven’t seen. We want to help fund the collaborations that bring those ideas to life.</p><a class="text-link" href="programs.html">Explore the vision ↗</a></div>'''+network+'''</div></section>
<section class="photo-strip" aria-label="Perspectives on the wild"><figure><img src="assets/photos/filmmaker-river.jpg" alt="A filmmaker working on a riverbank" loading="lazy"><figcaption>BEHIND THE LENS</figcaption></figure><figure><img src="assets/photos/field/tiger-rock.jpg" alt="A tiger moving across a rock ledge" loading="lazy"><figcaption>INTO THE WILD</figcaption></figure><figure><img src="assets/photos/reflection-jump.jpg" alt="An explorer leaping above a reflective salt flat" loading="lazy"><figcaption>OUT INTO THE WORLD</figcaption></figure></section>
<section class="section light"><div class="wrap"><div class="section-top"><div><p class="eyebrow">03 / Meet the moment</p><h2 class="reveal">Their world<br>is <em>online.</em><br>Let’s bring the wild into it.</h2></div><div class="stat-teaser reveal"><strong><span data-count="76">76</span><span class="unit">%</span></strong><p>of U.S. teens use YouTube daily.</p><span class="source-label">Pew Research Center · Ages 13–17 · 2025</span><a class="text-link" href="why-it-matters.html">See the bigger picture ↗</a></div></div></div></section>'''+cta()
home=home.replace(cta(),collaboration_concepts()+funding_band()+cta())

about=hero('Our mission','A generation<br>that <em>cares.</em>','We want the next generation to care about wildlife and want to get outside. Everything starts there.','penguin-colony.jpg')+'''<section class="section light"><div class="wrap two-col"><p class="eyebrow">Why we exist</p><div><h2 class="reveal">Wonder starts<br>with a <em>connection.</em></h2><p class="body-copy">A creature you never knew existed. A place you suddenly want to explore. A person whose curiosity becomes contagious. Stories can open the door to a lifelong relationship with nature.</p><p class="body-copy">We’re bringing storytellers together around content made for creator platforms, and working toward funding the projects they make together.</p></div></div></section><section class="section"><div class="wrap"><p class="eyebrow">How we get there</p><h2 class="reveal">Bring people together.<br>Let wonder <em>spread.</em></h2><div class="steps"><article class="reveal"><span>01</span><h3>Connect the storytellers.</h3><p>Connect filmmakers, photographers and digital creators who want to reach younger audiences on creator platforms.</p></article><article class="reveal"><span>02</span><h3>Back collaborations.</h3><p>Help fund creator-led projects that bring different voices and audiences together.</p></article><article class="reveal"><span>03</span><h3>Inspire a generation.</h3><p>Meet young people where they watch, spark their curiosity, and invite them outside.</p></article></div></div></section><section class="section light"><div class="wrap two-col"><h2 class="reveal">A shared purpose.<br><em>Many ways to tell it.</em></h2><div><p class="body-copy">From wildlife and wild places to oceans, forests and our changing climate, there are countless stories worth caring about.</p><p class="body-copy">Our focus is content made for YouTube, TikTok, Instagram and live-streaming platforms. We want to support and recognize the creators using those spaces to connect younger audiences with nature.</p><p class="body-copy">We’re developing the first funding opportunities. The application process and timing are still taking shape; the purpose is clear: help creators make more compelling wildlife stories together.</p></div></div></section>'''+cta()
page('about.html','The mission','Make the next generation care about wildlife and want to get outside by supporting collaborative content on creator platforms.',about)
community=hero('The vision / Made for creator platforms','New collaborators.<br>New audiences.<br><em>More wild.</em>','Help bring wildlife into the videos, feeds and live streams that young people choose to watch.','filmmaker-river.jpg')+'''<section class="section light"><div class="wrap"><p class="eyebrow">An invitation to the storytellers</p><h2 class="reveal">Different crafts.<br><em>Common ground.</em></h2><div class="steps"><article class="reveal"><span>01 / FILMMAKERS</span><h3>Bring your eye.</h3><p>Bring your fieldcraft and storytelling to a collaboration built for YouTube, short-form video or a creator’s channel.</p></article><article class="reveal"><span>02 / PHOTOGRAPHERS</span><h3>Bring your perspective.</h3><p>Bring the stories behind your images into Reels, creator videos and live conversations that spark curiosity.</p></article><article class="reveal"><span>03 / DIGITAL CREATORS</span><h3>Bring your curiosity.</h3><p>Bring your voice and your understanding of your audience. Collaborate with other storytellers to make wildlife part of their world.</p></article></div></div></section><section class="section"><div class="wrap two-col"><div><p class="eyebrow">The idea in action</p><h2 class="reveal">Great creators.<br><em>Shared possibilities.</em></h2><p class="body-copy">Think of the way streamers appear in each other’s worlds. One collaboration leads you to another person, another perspective, another reason to come back.</p><p class="body-copy">We want that spirit of collaboration in wildlife storytelling, backed by funding that helps creators make ambitious ideas happen on their own platforms.</p></div>'''+network+'''</div><div class="wrap collaboration-list"><article class="reveal"><span>01</span><h3>Cross paths.</h3><p>Meet someone outside your format, platform or usual circle.</p></article><article class="reveal"><span>02</span><h3>Make something together.</h3><p>A YouTube episode, a joint live stream, a short-form series, a shared adventure told across creator channels.</p></article><article class="reveal"><span>03</span><h3>Open up your worlds.</h3><p>Introduce your audience to each other and to a new side of nature.</p></article></div></section>'''+cta()
community=community.replace(cta(),collaboration_concepts()+funding_band()+cta())
page('programs.html','The vision','A vision for funding wildlife creator collaborations made for YouTube, TikTok, Instagram and live streams.',community)
join=hero('Be part of the beginning','The wild<br>needs <em>your voice.</em>','Join a community of wildlife storytellers, photographers and digital creators helping the next generation care and get outside.','salt-flat-sunset.jpg')+'''<section class="section light"><div class="wrap two-col"><div><p class="eyebrow">For the storytellers</p><h2 class="reveal">Bring your craft.<br>Bring your ideas.<br><em>Bring yourself.</em></h2><p class="body-copy">We’re developing funding opportunities for collaborative wildlife content on YouTube, TikTok, Instagram and live-streaming platforms. Register your interest in what comes next.</p><div class="join-note"><strong>Meeting us at Wildscreen?</strong><p>Come talk to Michael or Sienna about the creator collaborations you’d love to make and the stories young audiences should see.</p></div></div><div class="join-panel"><h3>Join the community.</h3><p class="interest-intro">Register your interest in connecting with other wildlife storytellers. Share your email or Instagram so we can get in touch.</p><form id="interest-form" action="https://formsubmit.co/sienna@mike-mcgovern.com" method="POST" data-delivery="active"><input type="hidden" name="_cc" value="zander@mike-mcgovern.com"><input type="hidden" name="_subject" value="Follow the Wild: new community interest"><input type="hidden" name="_template" value="table"><input type="text" name="_honey" tabindex="-1" autocomplete="off" hidden><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required><p class="contact-note" id="contact-help">Provide an email address or Instagram handle. You can share both if you like.</p><label for="email">Email address <span>Optional if you provide Instagram</span></label><input id="email" name="email" type="email" autocomplete="email" aria-describedby="contact-help"><label for="instagram">Instagram handle <span>Optional if you provide email</span></label><input id="instagram" name="instagram" placeholder="@yourhandle" autocapitalize="none" spellcheck="false" aria-describedby="contact-help"><fieldset><legend>What’s your craft? <span>Optional. Select all that fit.</span></legend><div class="chips"><label><input type="checkbox" name="craft" value="Film"><span>Films</span></label><label><input type="checkbox" name="craft" value="Photography"><span>Photography</span></label><label><input type="checkbox" name="craft" value="Digital content"><span>Digital content</span></label><label><input type="checkbox" name="craft" value="Live streams"><span>Live streams</span></label><label><input type="checkbox" name="craft" value="Other"><span>Something else</span></label></div></fieldset><fieldset><legend>Where do you create? <span>Optional. Select all that fit.</span></legend><div class="chips"><label><input type="checkbox" name="platform" value="YouTube"><span>YouTube</span></label><label><input type="checkbox" name="platform" value="TikTok"><span>TikTok</span></label><label><input type="checkbox" name="platform" value="Instagram"><span>Instagram</span></label><label><input type="checkbox" name="platform" value="Live streaming"><span>Live streaming</span></label><label><input type="checkbox" name="platform" value="Other"><span>Other</span></label></div></fieldset><label for="portfolio">Website or additional handles <span>Optional</span></label><input id="portfolio" name="portfolio" placeholder="Website or social handle"><label for="idea">What would you love to create, and with whom? <span>Optional</span></label><textarea id="idea" name="idea" rows="3"></textarea><p class="contact-note">By registering, you’re asking the Follow the Wild team to contact you about the community and collaborations. Your details are delivered by email through FormSubmit to Sienna and Zander. <a href="https://formsubmit.co/privacy.pdf" target="_blank" rel="noopener">FormSubmit privacy policy</a>.</p><button class="button" type="submit" disabled>Register interest <span>↗</span></button><p id="form-status" role="status"></p></form></div></div></section><section class="section"><div class="wrap two-col"><p class="eyebrow">A little more about us</p><div class="faq"><details><summary>Do I need a large audience?</summary><p>We’re interested in ideas that connect younger audiences with wildlife. You can express interest at any stage. Eligibility for future funding opportunities will be shared when those opportunities are ready.</p></details><details><summary>What kind of work is this for?</summary><p>Our focus is content created for creator platforms: YouTube videos, TikToks, Reels, live streams and other social formats that reach younger audiences. Filmmakers and photographers are welcome to bring their skills into that work.</p></details><details><summary>Am I joining a membership organization?</summary><p>You’re registering your interest in our creator community. There’s no membership fee or funding application here. We’ll follow up about ways to connect and collaborate.</p></details><details><summary>Can I apply for funding yet?</summary><p>Funding applications are not open. We’re developing the first opportunities, including how projects will be selected and supported.</p></details><details><summary>What’s the mission?</summary><p>To make the next generation care about wildlife and want to get outside. Supporting collaborations on creator platforms is how we aim to get there.</p></details></div></div></section>'''
page('get-involved.html','For creators','Express interest in future funding opportunities for collaborative wildlife content on creator platforms.',join)
pew='https://www.pewresearch.org/internet/2025/12/09/teens-social-media-and-ai-chatbots-2025/'
nielsen=[('July 2024','10.4','https://www.nielsen.com/news-center/2024/july-exhibits-rare-upswing-in-tv-viewing-amplified-by-streaming-and-first-days-of-summer-olympics-according-to-nielsens-the-gauge/'),('July 2025','13.4','https://www.nielsen.com/news-center/2025/youtube-netflix-ride-the-wave-of-summer-streaming-highs-in-nielsens-media-distributor-gauge/'),('July 2026','14.2','https://www.nielsen.com/news-center/2026/tv-usage-kicks-usual-summer-slowdown-fueled-by-world-cup-and-streaming-in-nielsens-july-gauge-reports/')]
bars=''.join(f'<div class="bar-row"><div class="bar-label"><span>{name}</span><b>{value}%</b></div><div class="bar-track"><div class="bar-fill" style="--value:{value}%;--delay:{i*.12}s"></div></div></div>' for i,(name,value) in enumerate([('YouTube',76),('TikTok',61),('Instagram',55),('Snapchat',46),('Facebook',20)]))
line='''<svg class="line-chart" viewBox="0 0 600 350" role="img" aria-labelledby="tv-chart-title tv-chart-desc"><title id="tv-chart-title">YouTube’s share of U.S. TV viewing</title><desc id="tv-chart-desc">July 2024: 10.4 percent. July 2025: 13.4 percent. July 2026: 14.2 percent. Annual July snapshots. Vertical axis runs from zero to sixteen percent.</desc><g class="grid"><path d="M55 290H570M55 225H570M55 160H570M55 95H570M55 30H570"/></g><g><text x="12" y="294">0%</text><text x="12" y="229">4%</text><text x="12" y="164">8%</text><text x="5" y="99">12%</text><text x="5" y="34">16%</text></g><path class="line-path" pathLength="1" d="M75 121L310 72.25L545 59.25"/><g><circle class="point" cx="75" cy="121" r="6"/><circle class="point" cx="310" cy="72.25" r="6"/><circle class="point" cx="545" cy="59.25" r="6"/><text class="value-label" x="75" y="99" text-anchor="middle">10.4%</text><text class="value-label" x="310" y="50" text-anchor="middle">13.4%</text><text class="value-label" x="545" y="37" text-anchor="middle">14.2%</text><text x="75" y="325" text-anchor="middle">JUL 2024</text><text x="310" y="325" text-anchor="middle">JUL 2025</text><text x="545" y="325" text-anchor="middle">JUL 2026</text></g></svg>'''
why='''<section class="why-hero"><div class="wrap"><p class="eyebrow">Why now / The audience has moved</p><h1>The next generation<br>is already <em>watching.</em></h1><p class="intro">Let’s give them a reason to care about the wild. Social video and creators are part of young people’s daily lives. Wildlife storytellers have an opportunity to meet them there.</p><a class="text-link" href="#daily">Follow the data ↓</a></div></section><section class="section light" id="daily"><div class="wrap"><div class="chapter"><span>01 / PART OF EVERY DAY</span><span>U.S. TEENS · 2025</span></div><div class="chart-layout"><div><h2 class="reveal">This is where<br>they <em>show up.</em></h2><p>More than three quarters of U.S. teens use YouTube daily. TikTok and Instagram are daily destinations for a majority, too.</p><p>To invite young people into the natural world, our stories need to be part of the places they already spend time.</p></div><div><h3 class="chart-head">Teens who use each platform daily</h3><div class="chart-sub">% of U.S. teens ages 13–17 · 2025</div><div class="chart" id="daily-chart" role="img" aria-label="Daily platform use among U.S. teens: YouTube 76 percent, TikTok 61 percent, Instagram 55 percent, Snapchat 46 percent, Facebook 20 percent.">'''+bars+'''<div class="chart-axis"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div></div><button class="replay" data-replay="daily-chart">↻ Replay chart</button><div class="chart-source">Source: <a href="'''+pew+'''" target="_blank" rel="noopener">Pew Research Center, December 2025 ↗</a><br>Survey of 1,458 U.S. teens, Sept. 25–Oct. 9, 2025. Daily includes several times a day, about once a day, and almost constantly. People use multiple platforms; percentages do not add to 100%.</div></div></div></div></section><section class="section dark-chart"><div class="wrap"><div class="chapter"><span>02 / BEYOND THE PHONE</span><span>U.S. TV VIEWING · JULY SNAPSHOTS</span></div><div class="chart-layout"><div><h2 class="reveal">The big screen<br>has changed<br><em>too.</em></h2><p>YouTube accounted for 14.2% of all U.S. TV viewing time in July 2026. The worlds of television and creator video increasingly share the same screen.</p><p>There’s room for wildlife storytelling across short videos, longer films and live streams. The opportunity crosses formats.</p></div><div><h3 class="chart-head">YouTube’s share of U.S. television viewing</h3><div class="chart-sub">% of total TV viewing time · All ages, not a youth-only measure</div><div class="chart" id="tv-chart">'''+line+'''</div><button class="replay" data-replay="tv-chart">↻ Replay chart</button><div class="chart-source">Source: Nielsen, The Gauge / Media Distributor Gauge.<br>'''+ ' · '.join(f'<a href="{url}" target="_blank" rel="noopener">{date} ↗</a>' for date,value,url in nielsen)+'''<br>YouTube viewing on TV screens, not the separate YouTube TV subscription service. Three July snapshots, not annual averages or monthly growth.</div><details class="data-notes"><summary>View data and measurement notes</summary><table><thead><tr><th scope="col">Period</th><th scope="col">Share</th></tr></thead><tbody>'''+''.join(f'<tr><th scope="row">{date}</th><td>{value}%</td></tr>' for date,value,url in nielsen)+'''</tbody></table><p>Measured periods: July 1–28, 2024; June 30–July 27, 2025; June 29–July 26, 2026. Lines connect the three observed July snapshots. They do not establish what happened in the intervening months.</p></details></div></div></div></section><section class="section light"><div class="wrap"><p class="eyebrow">03 / A wider shift</p><h2 class="reveal">New habits.<br><em>New possibilities.</em></h2><div class="evidence-pair"><article class="reveal"><strong>1B+</strong><h3>Hours. On TVs. Every day.</h3><p>Viewers worldwide watched more than one billion hours of YouTube on television sets daily, according to YouTube’s December 2024 recap.</p><div class="chart-source">Global viewing time · Company-reported · December 2024<br><a href="https://blog.youtube/news-and-events/2024-recap-of-youtube-on-tv/" target="_blank" rel="noopener">YouTube’s TV recap ↗</a></div></article><article class="reveal"><strong><span data-count="45">45</span>%</strong><h3>Weekly broadcast TV reach.</h3><p>In the UK, 45% of 16–24-year-olds watched broadcast TV in a typical week in 2024. Reaching young people means looking beyond the traditional broadcast schedule.</p><div class="chart-source">UK ages 16–24 · Weekly reach · 2024 data<br><a href="https://www.ofcom.org.uk/media-use-and-attitudes/media-habits-adults/tuning-into-youtube-uks-media-habits-revealed?language=en" target="_blank" rel="noopener">Ofcom, Media Nations 2025 ↗</a></div></article></div></div></section><section class="section"><div class="wrap"><div class="reading"><p class="eyebrow">What this means for the wild</p><h2 class="reveal">Attention is<br>an <em>opening.</em><br>Connection is the goal.</h2><p>These numbers show where audiences are. Our mission gives us a reason to meet them there.</p><p>By helping creators collaborate and funding the work they make together, we aim to put more wildlife, nature and climate stories into the videos and streams young people choose to watch.</p><p>The goal goes beyond a view: a young person who becomes curious, starts caring, and wants to step outside.</p><a class="text-link" href="programs.html">Explore creator collaborations ↗</a><p class="method-note">These studies measure media use. They do not measure the effect of Follow the Wild or prove that watching wildlife content leads to outdoor activity or conservation action.</p></div></div></section>'''+cta()
page('why-it-matters.html','Why now','The data behind our mission: youth social video use and the changing role of YouTube on television, with sources from Pew, Nielsen, Ofcom and YouTube.',why)
support=hero('Support the mission','Fund the stories.<br><em>Inspire a generation.</em>','Help creators bring wildlife into the videos, feeds and live streams young people choose to watch.','humpback-dive.jpg')+'''<section class="section light" id="donate"><div class="wrap donation-layout"><div><p class="eyebrow">Help build the first collaborations</p><h2 class="reveal">A shared idea.<br>A new audience.<br><em>Your support.</em></h2><p class="body-copy">We want to fund wildlife projects made by creators working together, combining their perspectives and introducing their audiences to more of the natural world.</p><p class="body-copy">That’s the ambition behind Follow the Wild: help the next generation care about wildlife and want to get outside.</p><a class="text-link" href="programs.html#possibilities">Explore what creators could make ↗</a></div><div class="donation-card"><div class="donation-card-top"><span class="eyebrow">Back the vision</span><span class="demo-badge">DEMO</span></div><h3>Give the wild<br>a bigger audience.</h3><p>Choose an amount to preview a donation.</p><form id="donation-form"><fieldset><legend>One-time gift <span>USD</span></legend><div class="donation-amounts"><label><input type="radio" name="amount" value="25"><span>$25</span></label><label><input type="radio" name="amount" value="50" checked><span>$50</span></label><label><input type="radio" name="amount" value="100"><span>$100</span></label><label><input type="radio" name="amount" value="250"><span>$250</span></label><label class="custom-option"><input type="radio" name="amount" value="custom"><span>Choose your own amount</span></label></div></fieldset><div id="custom-amount-wrap" hidden><label for="custom-amount">Your amount in USD</label><input id="custom-amount" type="number" inputmode="decimal" min="1" step="0.01" placeholder="50.00" disabled></div><button class="button donation-submit" type="submit" disabled><span id="donate-label">Donate $50</span><span aria-hidden="true">↗</span></button><p class="donation-disclosure">Demo only. No payment is taken and no information is collected.</p><p id="donation-status" role="status"></p></form><noscript><p>This donation preview needs JavaScript. No donations can be processed here.</p></noscript></div></div></section><section class="section"><div class="wrap"><p class="eyebrow">The funding vision</p><h2 class="reveal">More creators together.<br><em>More room for the wild.</em></h2><div class="steps"><article class="reveal"><span>01 / CREATOR PLATFORMS</span><h3>Made for their world.</h3><p>Content built for YouTube, TikTok, Instagram and live streams, with young audiences in mind from the start.</p></article><article class="reveal"><span>02 / COLLABORATION</span><h3>Made together.</h3><p>Projects that bring creators’ skills, perspectives and audiences into the same story.</p></article><article class="reveal"><span>03 / CONNECTION</span><h3>Made to spark wonder.</h3><p>Wildlife stories that make someone curious enough to care, explore and see the natural world for themselves.</p></article></div><p class="funding-stage">We’re developing our first funding opportunities. Project selection, funding amounts and launch timing will be shared as the program takes shape.</p></div></section><dialog id="donation-dialog" aria-labelledby="donation-dialog-title" aria-describedby="donation-dialog-description"><span class="demo-badge">DONATION PREVIEW</span><h2 id="donation-dialog-title">A gift for<br><em>the wild.</em></h2><p id="donation-preview-amount"></p><p id="donation-dialog-description">This is a demonstration of the donation experience. No payment has been taken, no pledge has been recorded, and no information has been collected.</p><button class="button" id="close-donation" type="button">Back to the vision <span aria-hidden="true">↗</span></button></dialog>'''
page('support.html','Support the mission','Help build funding for wildlife creator collaborations that inspire younger audiences. Explore our donation demo.',support)

# The same sourced charts appear immediately after the home hero.
import re
home=re.sub(r'<div class="platform-statement">.*?(?=<section class="section light" id="the-idea")', '', home, flags=re.S)
home=re.sub(r'<section class="section light"><div class="wrap"><div class="section-top"><div><p class="eyebrow">03 / Meet the moment.*?(?=<section class="section concepts")', '', home, flags=re.S)
audience = '<section class="section light audience-opening" id="audience"><div class="wrap"><p class="eyebrow">A new generation. A different world.</p><h2 class="reveal">Their attention is here.<br><em>Let’s bring the wild.</em></h2><p class="audience-intro">Creators are shaping what the next generation watches, shares and cares about. This is where our story begins.</p></div></section>'
start=why.index('<section class="section light" id="daily">')
end=why.index('<section class="section"><div class="wrap"><div class="reading">')
audience += why[start:end].replace('id="daily"','id="home-daily"').replace('daily-chart','home-daily-chart').replace('tv-chart','home-tv-chart')
audience += '<div class="audience-link wrap"><a class="text-link" href="why-it-matters.html">Explore the full picture →</a></div>'
photo_panels = '<section class="restored-panels" id="photo-panels" aria-label="Inspire, explore, discover and protect"><div class="wrap panel-intro"><p class="eyebrow">Stories that bring us together</p><h2>More voices.<br><em>More of the wild.</em></h2></div>'
for word,caption,photo,alt,link in [
 ('Inspire','Stories that make the next generation care.','elephants-zebra.jpg','Elephants and a zebra at a watering hole','programs.html'),
 ('Explore','Spark curiosity. Invite people outside.','sunset-jump.jpg','Two people jumping against a sunset over the water','about.html'),
 ('Discover','New collaborators. New perspectives. New audiences.','filmmaker-river.jpg','A wildlife filmmaker beside a river','get-involved.html'),
 ('Protect','Help a generation care about the future of the wild.','humpback-dive.jpg','A humpback whale diving below the surface','support.html')]:
 photo_panels += f'<a class="restored-band" href="{link}"><img src="assets/photos/{photo}" alt="{alt}" loading="lazy"><div class="wrap"><h3>{word}</h3><p>{caption}</p><span class="panel-link">Explore the vision →</span></div></a>'
photo_panels += '</section>'
pos=home.index('</section>')+len('</section>')
home=home[:pos]+photo_panels+audience+home[pos:]
home='<svg class="trail-line" aria-hidden="true" data-from="#photo-panels" data-to=".closing"></svg>'+home
home=home.replace('href="#the-idea"','href="#photo-panels"')
page('index.html','For the next generation','Supporting wildlife creator collaborations for YouTube, TikTok, Instagram and live streams, to inspire the next generation to care and get outside.',home)

